            SpaceConfigMutation::SetSpaceId { space_id } => next.space_id = space_id.clone(),
            SpaceConfigMutation::SetActivePanelTab { tab_id } => next.active_panel_tab = tab_id.clone(),
        }
        protocol::MutationOutcome::new(next)
    }

